CREATE OR REPLACE FUNCTION public.assign_workspace_account(target_user uuid, additional_role public.app_role, target_client uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF additional_role NOT IN ('admin','staff','client') THEN RAISE EXCEPTION 'Unsupported role'; END IF; IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id=target_user) THEN RAISE EXCEPTION 'The account must sign up first'; END IF; IF target_client IS NOT NULL THEN PERFORM id FROM public.clients WHERE id=target_client FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Client company not found'; END IF; IF EXISTS (SELECT 1 FROM public.clients WHERE id=target_client AND user_id IS NOT NULL AND user_id<>target_user) THEN RAISE EXCEPTION 'This company is already linked to another account'; END IF; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(target_user,additional_role) ON CONFLICT(user_id,role) DO NOTHING; UPDATE public.clients SET user_id=NULL WHERE user_id=target_user AND (target_client IS NULL OR id<>target_client); IF target_client IS NOT NULL THEN UPDATE public.clients SET user_id=target_user WHERE id=target_client; END IF; END $$;
REVOKE ALL ON FUNCTION public.assign_workspace_account(uuid,public.app_role,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.assign_workspace_account(uuid,public.app_role,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.guard_client_account_link() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF ((TG_OP='INSERT' AND NEW.user_id IS NOT NULL) OR (TG_OP='UPDATE' AND NEW.user_id IS DISTINCT FROM OLD.user_id)) AND auth.role()<>'service_role' AND NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Only administrators can link accounts'; END IF; RETURN NEW; END $$;
CREATE TRIGGER clients_account_link BEFORE INSERT OR UPDATE ON public.clients FOR EACH ROW EXECUTE FUNCTION public.guard_client_account_link();
CREATE OR REPLACE FUNCTION public.remove_presentation_records() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Administrator access required'; END IF;
IF EXISTS(SELECT 1 FROM public.client_projects p JOIN public.clients c ON c.id=p.client_id WHERE c.is_demo AND NOT p.is_demo) OR EXISTS(SELECT 1 FROM public.support_tickets t LEFT JOIN public.clients c ON c.id=t.client_id LEFT JOIN public.client_projects p ON p.id=t.project_id WHERE (c.is_demo OR p.is_demo) AND NOT t.is_demo) OR EXISTS(SELECT 1 FROM public.invoices i LEFT JOIN public.clients c ON c.id=i.client_id LEFT JOIN public.client_projects p ON p.id=i.project_id WHERE (c.is_demo OR p.is_demo) AND NOT i.is_demo) OR EXISTS(SELECT 1 FROM public.project_documents d JOIN public.client_projects p ON p.id=d.project_id WHERE p.is_demo AND NOT d.is_demo) OR EXISTS(SELECT 1 FROM public.project_messages m JOIN public.client_projects p ON p.id=m.project_id WHERE p.is_demo AND NOT m.is_demo) OR EXISTS(SELECT 1 FROM public.project_milestones m JOIN public.client_projects p ON p.id=m.project_id WHERE p.is_demo AND NOT m.is_demo) OR EXISTS(SELECT 1 FROM public.invoice_items x JOIN public.invoices i ON i.id=x.invoice_id WHERE i.is_demo AND NOT x.is_demo) OR EXISTS(SELECT 1 FROM public.payments x JOIN public.invoices i ON i.id=x.invoice_id WHERE i.is_demo AND NOT x.is_demo) THEN RAISE EXCEPTION 'Real records are linked to presentation data. Move them before removing samples'; END IF;
DELETE FROM public.payments WHERE is_demo=true; DELETE FROM public.invoice_items WHERE is_demo=true; DELETE FROM public.invoices WHERE is_demo=true; DELETE FROM public.support_tickets WHERE is_demo=true; DELETE FROM public.project_messages WHERE is_demo=true; DELETE FROM public.project_documents WHERE is_demo=true; DELETE FROM public.project_milestones WHERE is_demo=true; DELETE FROM public.client_projects WHERE is_demo=true; DELETE FROM public.clients WHERE is_demo=true; DELETE FROM public.submission_drafts WHERE submission_id IN (SELECT id FROM public.contact_messages WHERE is_demo UNION ALL SELECT id FROM public.quote_requests WHERE is_demo UNION ALL SELECT id FROM public.job_applications WHERE is_demo); DELETE FROM public.contact_messages WHERE is_demo=true; DELETE FROM public.quote_requests WHERE is_demo=true; DELETE FROM public.job_applications WHERE is_demo=true; END $$;
REVOKE ALL ON FUNCTION public.remove_presentation_records() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.remove_presentation_records() TO authenticated,service_role;